from typing import Annotated, Any
from fastapi import FastAPI, Query
from pydantic import BeforeValidator, WithJsonSchema
import pytest

app = FastAPI()

FilterableStr = Annotated[
    str | dict,
    BeforeValidator(lambda x: x),
    WithJsonSchema({"type": "string"}, mode="serialization"),
]

def test_invalid_query_param():
    try:
        @app.get("/hello")
        async def get_hello(data: FilterableStr | None = Query(default=None)) -> Any:
            return data
    except AssertionError as e:
        print(f"Caught expected AssertionError: {e}")
        # Check if the error message is what we expect
        if str(e) == "Query param 'data' must be of one of the supported types":
            print("Success: Error message is correct")
        else:
            print(f"Failure: Error message is '{e}', expected 'Query param 'data' must be of one of the supported types'")
            raise e
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
        raise e
    else:
        print("Failure: No AssertionError was raised")
        raise AssertionError("No AssertionError was raised")

if __name__ == "__main__":
    test_invalid_query_param()

